css:
.print-format {
    font-family: Arial, sans-serif;
    font-size: 11px;
    padding: 30px;
}
.verifactu-qr-block {
    text-align: center;
    margin-bottom: 12px;
}
.verifactu-qr-block .verifactu-qr-label {
    font-size: 10px;
    font-weight: bold;
    margin-bottom: 2px;
}
.verifactu-qr-block img {
    /* 30-40mm exigidos por el art. 21 de la Orden (RD 1007/2023) */
    width: 35mm;
    height: 35mm;
}
.verifactu-qr-block .verifactu-qr-caption {
    font-size: 10px;
    font-weight: bold;
    margin-top: 2px;
}
.verifactu-items-table th, .verifactu-items-table td {
    border: 1px solid #444;
    padding: 4px 6px;
    font-size: 11px;
}
.verifactu-totals td {
    padding: 2px 6px;
}
